import RNA, random
t='.(((.(((...(((.(((...))).(((....))).)))...(((.(((....))).(((...))).)))...(((.(((....))).(((...))).)))...))).(((...))).))).'
n=len(t)
stack=[]; pairs={}
for i,c in enumerate(t):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

# Build seed: G-C closing pairs everywhere, A in loops, but vary stem
seq=['A']*n
# closing pairs get GC, internal stem GC too
for i,j in pairs.items():
    if i<j:
        seq[i]='G'; seq[j]='C'

# Apply hairpin caps: triloop->GAA, tetraloop->GAAA, on closing C-G
# triloop closing pair C-G (i=C, j=G) so cap goes inside loop
caps={3:'GAA',4:'GAAA',5:'GAAAA'}
hairpins=[(17,21,3),(27,32,4),(48,53,4),(59,63,3),(79,84,4),(90,94,3),(110,114,3)]
for i,j,L in hairpins:
    loop_seq=caps.get(L,'G'+'A'*(L-1))
    for k,ch in enumerate(loop_seq):
        if i+1+k < j-1:
            seq[i+1+k]=ch
    # also UUCG for tetraloop? keep GAAA for stability

seq=''.join(seq)
print(seq)
fc=RNA.fold_compound(seq)
ss,mfe=fc.mfe()
print(ss)
print('mfe',mfe,'match',ss==t)
