        j=stack.pop(); pairs[j]=i; pairs[i]=j
target_pairs=set()
for i,j in pairs.items():
    if i<j: target_pairs.add((i,j))

def fold_pairs(ss):
    s2=set(); st=[]
    for i,c in enumerate(ss):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); s2.add((j,i))
    return s2
def score(ss):
    return len(target_pairs ^ fold_pairs(ss))

